const fs = require('node:fs');
const { buildSync } = require('esbuild');

const result = buildSync({
  entryPoints: ['lib/fit-core.mjs'], bundle: true, write: false,
  format: 'iife', globalName: 'FITCore', platform: 'browser', target: 'chrome110',
  minify: true, legalComments: 'inline',
});
const core = '// Generated by npm run build. Garmin FIT SDK license: licenses/Garmin-FIT-SDK.txt\n' +
  result.outputFiles[0].text + '\nself.FIT = FITCore;\n';
const page = fs.readFileSync('page-fetch.template.js', 'utf8').replace('/* FIT_CORE */', core + '\nconst FIT = self.FIT;');
if (process.argv.includes('--check')) {
  if (fs.readFileSync('lib/fit-parser.js', 'utf8') !== core || fs.readFileSync('page-fetch.js', 'utf8') !== page) {
    throw new Error('FIT bundles are stale; run npm run build');
  }
} else {
  fs.writeFileSync('lib/fit-parser.js', core);
  fs.writeFileSync('page-fetch.js', page);
}
